/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb']
f0 = d[0]
# coarse map: sample every 4 px, classify
H,W,_ = f0.shape
chars = ' .:-=+*#%@'
for y in range(0,H,4):
    line=''
    for x in range(0,W,4):
        r,g,b = f0[y,x].astype(int)
        # redness
        if r>140 and r-g>50 and r-b>50:
            c='R'
        elif r>200 and g>190 and b>170:
            c='.'  # light bg
        elif abs(r-g)<25 and abs(g-b)<25 and r<100:
            c='#'
        elif g>r+20 and g>b+10:
            c='G'
        elif b>r+20 and b>g+10:
            c='B'
        elif r>150 and g>120 and b<120:
            c='o'  # wood/orange
        else:
            c='?'
        line+=c
    print(line)
\""
